export const overdue: Handler = (_req, ctx) => {
  const now = ctx.clock.now().getTime();
  const DAY = 24 * 60 * 60 * 1000;
  const late = ctx.store.invoices
    .find((i) => i.status === 'open' && new Date(i.dueAt).getTime() < now)
    .sort((a, b) => a.dueAt.localeCompare(b.dueAt) || a.id.localeCompare(b.id));
  return ok(late.map((i) => ({ ...i, daysOverdue: Math.max(1, Math.floor((now - new Date(i.dueAt).getTime()) / DAY)) })));
};
